from math import comb

def count_k_bits(queries):
    def upto(n, k):
        if n < 0:
            return 0
        count, used = 0, 0
        for b in range(n.bit_length() - 1, -1, -1):
            if n >> b & 1:
                if used <= k:
                    count += comb(b, k - used)
                used += 1
        if used == k:
            count += 1
        return count
    return [upto(hi, k) - upto(lo - 1, k) for lo, hi, k in queries]

