def count_k_bits(queries):
    out = []
    for lo, hi, k in queries:
        if k == 0:
            out.append(1 if lo == 0 else 0)
            continue
        x, count = (1 << k) - 1, 0
        while x <= hi:
            if x >= lo:
                count += 1
            low = x & -x
            ripple = x + low
            x = ripple | (((x ^ ripple) >> 2) // low)
        out.append(count)
    return out
